//! Bounded payload parsing and request recovery for the batch example.

use super::*;

/// Normalize payload integer errors without hiding checked-i64 overflow.
fn integer(text: &str) -> Result<Number> {
    parse_number(text).map_err(|error| {
        if error.kind == "ValueError" {
            Error::new("ValueError", "invalid integer")
        } else {
            error
        }
    })
}

/// A huge count still parses earlier rows before reaching the bounded frame end.
fn count(text: &str, negative_message: &'static str) -> Result<usize> {
    let value = integer(text)?;
    if value < Number::from(0) {
        return Err(Error::new("ValueError", negative_message));
    }
    Ok(as_index(&value).unwrap_or(usize::MAX))
}

fn take<'a>(lines: &'a [String], position: &mut usize) -> Result<&'a str> {
    let line = lines
        .get(*position)
        .ok_or_else(|| Error::new("IndexError", "truncated payload"))?;
    *position += 1;
    Ok(line)
}

/// Preserve row parsing order and partial-allocation cleanup before recovery.
fn parse(lines: &[String]) -> Result<(Vec<Task>, Vec<String>)> {
    let mut position = 0;
    let task_count = count(take(lines, &mut position)?, "negative target count")?;
    let mut tasks = Vec::new();
    for _ in 0..task_count {
        let words: Vec<&str> = take(lines, &mut position)?
            .split(python_whitespace)
            .filter(|word| !word.is_empty())
            .collect();
        if words.len() < 2 {
            return Err(Error::new(
                "AssertionError",
                "target row needs a name and duration",
            ));
        }
        let mut dependencies = Vec::new();
        for (index, word) in words.iter().enumerate() {
            if index >= 2 {
                dependencies.push((*word).to_owned());
            }
        }
        tasks.push(Task {
            name: words[0].to_owned(),
            duration: integer(words[1])?,
            dependencies,
        });
    }
    let change_count = count(take(lines, &mut position)?, "negative change count")?;
    let mut changes = Vec::new();
    for _ in 0..change_count {
        let words: Vec<&str> = take(lines, &mut position)?
            .split(python_whitespace)
            .filter(|word| !word.is_empty())
            .collect();
        if words.len() != 1 {
            return Err(Error::new(
                "AssertionError",
                "change row needs exactly one name",
            ));
        }
        changes.push(words[0].to_owned());
    }
    Ok((tasks, changes))
}

/// The buffer is cleared and END is emitted for both recovered and escaping errors.
fn process(
    lines: &mut Vec<String>,
    request_id: usize,
    output: &mut Output<impl Write>,
) -> Result<bool> {
    output.line("REQUEST")?;
    output.line(request_id)?;
    let result = (|| {
        let (tasks, changes) = match parse(lines) {
            Ok(problem) => problem,
            Err(error) if matches!(error.kind, "ValueError" | "IndexError" | "AssertionError") => {
                output.line("INVALID")?;
                output.line(error.kind)?;
                output.line(error.message)?;
                return Ok(false);
            }
            Err(error) => return Err(error),
        };
        show(&schedule(&tasks, &changes)?, output)?;
        Ok(true)
    })();
    lines.clear();
    output.line("END")?;
    output.line(request_id)?;
    result
}

fn run(reader: &mut impl BufRead, output: &mut Output<impl Write>) -> Result<()> {
    let request_count = read_count(reader)?;
    let mut completed = 0;
    let mut invalid = 0;
    let mut cleaned = 0;
    for request_id in 0..request_count {
        let line_count = read_count(reader)?;
        let mut lines = Vec::new();
        for _ in 0..line_count {
            lines.push(input(reader)?);
        }
        if process(&mut lines, request_id, output)? {
            completed += 1;
        } else {
            invalid += 1;
        }
        debug_assert!(lines.is_empty());
        cleaned += 1;
    }
    output.line("SUMMARY")?;
    output.line("COMPLETED")?;
    output.line(completed)?;
    output.line("INVALID")?;
    output.line(invalid)?;
    output.line("CLEANED")?;
    output.line(cleaned)?;
    output.flush()
}

pub(super) fn main() -> ExitCode {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut output = Output::new(stdout.lock(), stdout.is_terminal());
    match run(&mut stdin.lock(), &mut output) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            let _ = output.flush();
            let _ = writeln!(io::stderr().lock(), "{}: {}", error.kind, error.message);
            ExitCode::FAILURE
        }
    }
}

//! Framed-request entrypoint sharing the unchanged incremental graph algorithm.

#[path = "main.rs"]
#[allow(dead_code)]
mod planner;

fn main() -> std::process::ExitCode {
    planner::batch_main()
}

//! Direct Rust port of the named incremental planner, with two numeric domains.

use std::collections::{HashMap, HashSet};
use std::fmt::Display;
use std::io::{self, BufRead, BufWriter, IsTerminal, Write};
use std::process::ExitCode;

#[cfg(feature = "batch")]
#[path = "batch.rs"]
mod batch;

/// Run the framed-request entrypoint while sharing the original graph algorithm.
#[cfg(feature = "batch")]
pub fn batch_main() -> ExitCode {
    batch::main()
}

#[cfg(all(feature = "bigint", feature = "checked-i64"))]
compile_error!("select exactly one numeric mode: bigint or checked-i64");
#[cfg(not(any(feature = "bigint", feature = "checked-i64")))]
compile_error!("select exactly one numeric mode: bigint or checked-i64");

#[cfg(feature = "bigint")]
use num_traits::ToPrimitive;
#[cfg(feature = "bigint")]
type Number = num_bigint::BigInt;
#[cfg(feature = "checked-i64")]
type Number = i64;

type Result<T> = std::result::Result<T, Error>;

struct Error {
    kind: &'static str,
    message: &'static str,
}

impl Error {
    fn new(kind: &'static str, message: &'static str) -> Self {
        Self { kind, message }
    }
}

struct Task {
    name: String,
    duration: Number,
    dependencies: Vec<String>,
}

enum Detail<'a> {
    Name(&'a str),
    Duration(&'a Number),
}

struct GraphError<'a> {
    kind: &'static str,
    index: usize,
    detail: Detail<'a>,
}

struct Plan<'a> {
    tasks: &'a [Task],
    order: Vec<usize>,
    starts: Vec<Number>,
    finishes: Vec<Number>,
    changed_count: usize,
    makespan: Number,
    error: Option<GraphError<'a>>,
}

/// Match the Python runtime's pipe buffering and terminal newline visibility.
struct Output<W: Write> {
    writer: BufWriter<W>,
    line_buffered: bool,
}

impl<W: Write> Output<W> {
    fn new(writer: W, line_buffered: bool) -> Self {
        Self {
            writer: BufWriter::with_capacity(8 * 1024, writer),
            line_buffered,
        }
    }

    fn line(&mut self, value: impl Display) -> Result<()> {
        writeln!(self.writer, "{value}")
            .map_err(|_| Error::new("OSError", "could not write standard output"))?;
        if self.line_buffered {
            self.flush()?;
        }
        Ok(())
    }

    fn flush(&mut self) -> Result<()> {
        self.writer
            .flush()
            .map_err(|_| Error::new("OSError", "could not write standard output"))
    }
}

/// Python's separator-free split includes these four additional ASCII controls.
fn python_whitespace(value: char) -> bool {
    value.is_whitespace() || matches!(value, '\u{001c}'..='\u{001f}')
}

/// Accept ASCII decimal digits, one sign, and underscores only between digits.
fn parse_number(source: &str) -> Result<Number> {
    let source = source.trim();
    let digits = source.strip_prefix(['+', '-']).unwrap_or(source);
    if digits.is_empty()
        || digits.starts_with('_')
        || digits.ends_with('_')
        || digits.contains("__")
        || !digits
            .bytes()
            .all(|value| value.is_ascii_digit() || value == b'_')
    {
        return Err(Error::new(
            "ValueError",
            "expected an ASCII decimal integer",
        ));
    }
    let normalized = source.replace('_', "");
    #[cfg(feature = "bigint")]
    {
        Number::parse_bytes(normalized.as_bytes(), 10)
            .ok_or_else(|| Error::new("ValueError", "invalid integer input"))
    }
    #[cfg(feature = "checked-i64")]
    {
        normalized
            .parse::<Number>()
            .map_err(|_| Error::new("OverflowError", "integer exceeds signed 64-bit range"))
    }
}

/// Counts and IDs must fit addressable storage in both numeric modes.
fn as_index(value: &Number) -> Option<usize> {
    #[cfg(feature = "bigint")]
    {
        value.to_usize()
    }
    #[cfg(feature = "checked-i64")]
    {
        usize::try_from(*value).ok()
    }
}

/// The bounded reference rejects overflow rather than wrapping scheduled times.
fn add(left: &Number, right: &Number) -> Result<Number> {
    #[cfg(feature = "bigint")]
    {
        Ok(left + right)
    }
    #[cfg(feature = "checked-i64")]
    {
        left.checked_add(*right).ok_or_else(|| {
            Error::new(
                "OverflowError",
                "rebuild finish exceeds signed 64-bit range",
            )
        })
    }
}

/// Remove LF only; the token splitter handles a retained CR from CRLF input.
fn input(reader: &mut impl BufRead) -> Result<String> {
    let mut line = String::new();
    let length = reader
        .read_line(&mut line)
        .map_err(|_| Error::new("OSError", "could not read standard input"))?;
    if length == 0 {
        return Err(Error::new("EOFError", "EOF when reading a line"));
    }
    if line.ends_with('\n') {
        line.pop();
    }
    Ok(line)
}

fn read_count(reader: &mut impl BufRead) -> Result<usize> {
    let count = parse_number(&input(reader)?)?;
    if count < Number::from(0) {
        return Err(Error::new("AssertionError", "count must be nonnegative"));
    }
    as_index(&count).ok_or_else(|| Error::new("OverflowError", "count exceeds addressable memory"))
}

/// Read every row before graph validation, matching the package's error phases.
fn read_problem(reader: &mut impl BufRead) -> Result<(Vec<Task>, Vec<String>)> {
    let count = read_count(reader)?;
    let mut tasks = Vec::new();
    for _ in 0..count {
        let line = input(reader)?;
        let words: Vec<&str> = line
            .split(python_whitespace)
            .filter(|word| !word.is_empty())
            .collect();
        if words.len() < 2 {
            return Err(Error::new(
                "AssertionError",
                "target line requires a name and duration",
            ));
        }
        let mut dependencies = Vec::new();
        for (position, word) in words.iter().enumerate() {
            if position >= 2 {
                dependencies.push((*word).to_owned());
            }
        }
        tasks.push(Task {
            name: words[0].to_owned(),
            duration: parse_number(words[1])?,
            dependencies,
        });
    }
    let changed_count = read_count(reader)?;
    let mut changes = Vec::new();
    for _ in 0..changed_count {
        let line = input(reader)?;
        let words: Vec<&str> = line
            .split(python_whitespace)
            .filter(|word| !word.is_empty())
            .collect();
        if words.len() != 1 {
            return Err(Error::new(
                "AssertionError",
                "change line requires one name",
            ));
        }
        changes.push(words[0].to_owned());
    }
    Ok((tasks, changes))
}

/// Use the same sift-up operation as the Python source.
fn push_ready(ready: &mut Vec<usize>, task_id: usize) {
    ready.push(task_id);
    let mut position = ready.len() - 1;
    while position > 0 {
        let parent = (position - 1) / 2;
        if ready[parent] <= task_id {
            break;
        }
        ready[position] = ready[parent];
        position = parent;
    }
    ready[position] = task_id;
}

/// Vec's addressable capacity bounds make the child-index arithmetic fit usize.
fn pop_ready(ready: &mut Vec<usize>) -> usize {
    let result = ready[0];
    let last = ready.pop().expect("pop_ready requires a nonempty heap");
    let count = ready.len();
    if count > 0 {
        let mut position = 0;
        while position * 2 + 1 < count {
            let mut child = position * 2 + 1;
            if child + 1 < count && ready[child + 1] < ready[child] {
                child += 1;
            }
            if ready[child] >= last {
                break;
            }
            ready[position] = ready[child];
            position = child;
        }
        ready[position] = last;
    }
    result
}

fn failure<'a>(
    tasks: &'a [Task],
    kind: &'static str,
    index: usize,
    detail: Detail<'a>,
) -> Plan<'a> {
    Plan {
        tasks,
        order: Vec::new(),
        starts: Vec::new(),
        finishes: Vec::new(),
        changed_count: 0,
        makespan: Number::from(0),
        error: Some(GraphError {
            kind,
            index,
            detail,
        }),
    }
}

/// Preserve name-resolution phases, deduplication, whole-graph validation, set
/// closure, and both handwritten heap passes. Hash order never controls output.
// The shared Number alias needs owned clones in BigInt mode and copies in i64 mode.
#[cfg_attr(feature = "checked-i64", allow(clippy::clone_on_copy))]
fn schedule<'a>(tasks: &'a [Task], changes: &'a [String]) -> Result<Plan<'a>> {
    let count = tasks.len();
    let mut names: HashMap<&str, usize> = HashMap::new();
    for (task_id, task) in tasks.iter().enumerate() {
        if names.contains_key(task.name.as_str()) {
            return Ok(failure(
                tasks,
                "duplicate-name",
                task_id,
                Detail::Name(&task.name),
            ));
        }
        names.insert(&task.name, task_id);
    }
    // Python dict.items() follows insertion order; task order is the same order.
    for (task_id, task) in tasks.iter().enumerate() {
        if task.duration < Number::from(0) {
            return Ok(failure(
                tasks,
                "negative-duration",
                task_id,
                Detail::Duration(&task.duration),
            ));
        }
    }
    let mut dependencies: Vec<Vec<usize>> = Vec::new();
    let mut successors: Vec<Vec<usize>> = Vec::new();
    for _ in tasks {
        dependencies.push(Vec::new());
        successors.push(Vec::new());
    }
    let mut indegrees = vec![0_usize; count];
    for (task_id, task) in tasks.iter().enumerate() {
        let mut seen: HashSet<&str> = HashSet::new();
        for name in &task.dependencies {
            if !seen.contains(name.as_str()) {
                let Some(&dependency) = names.get(name.as_str()) else {
                    return Ok(failure(
                        tasks,
                        "unknown-dependency",
                        task_id,
                        Detail::Name(name),
                    ));
                };
                seen.insert(name);
                dependencies[task_id].push(dependency);
                successors[dependency].push(task_id);
                indegrees[task_id] += 1;
            }
        }
    }
    let mut changed = HashSet::new();
    for (change_id, name) in changes.iter().enumerate() {
        let Some(&task_id) = names.get(name.as_str()) else {
            return Ok(failure(
                tasks,
                "unknown-change",
                change_id,
                Detail::Name(name),
            ));
        };
        changed.insert(task_id);
    }
    let mut ready = Vec::new();
    for (task_id, &degree) in indegrees.iter().enumerate() {
        if degree == 0 {
            push_ready(&mut ready, task_id);
        }
    }
    let mut completed = 0;
    while !ready.is_empty() {
        let task_id = pop_ready(&mut ready);
        completed += 1;
        for &child in &successors[task_id] {
            indegrees[child] -= 1;
            if indegrees[child] == 0 {
                push_ready(&mut ready, child);
            }
        }
    }
    if completed != count {
        for (task_id, &degree) in indegrees.iter().enumerate() {
            if degree > 0 {
                return Ok(failure(
                    tasks,
                    "cycle",
                    task_id,
                    Detail::Name(&tasks[task_id].name),
                ));
            }
        }
    }

    let mut affected = HashSet::new();
    let mut queue = Vec::new();
    for &task_id in &changed {
        affected.insert(task_id);
        queue.push(task_id);
    }
    let mut cursor = 0;
    while cursor < queue.len() {
        let task_id = queue[cursor];
        for &child in &successors[task_id] {
            if !affected.contains(&child) {
                affected.insert(child);
                queue.push(child);
            }
        }
        cursor += 1;
    }
    let mut starts = vec![Number::from(0); count];
    let mut finishes = vec![Number::from(0); count];
    let mut remaining = vec![0_usize; count];
    for task_id in 0..count {
        if affected.contains(&task_id) {
            for dependency in &dependencies[task_id] {
                if affected.contains(dependency) {
                    remaining[task_id] += 1;
                }
            }
            if remaining[task_id] == 0 {
                push_ready(&mut ready, task_id);
            }
        }
    }
    let mut order = Vec::new();
    let mut makespan = Number::from(0);
    while !ready.is_empty() {
        let task_id = pop_ready(&mut ready);
        order.push(task_id);
        finishes[task_id] = add(&starts[task_id], &tasks[task_id].duration)?;
        if finishes[task_id] > makespan {
            makespan = finishes[task_id].clone();
        }
        for &child in &successors[task_id] {
            if finishes[task_id] > starts[child] {
                starts[child] = finishes[task_id].clone();
            }
            remaining[child] -= 1;
            if remaining[child] == 0 {
                push_ready(&mut ready, child);
            }
        }
    }
    assert_eq!(order.len(), affected.len());
    Ok(Plan {
        tasks,
        order,
        starts,
        finishes,
        changed_count: changed.len(),
        makespan,
        error: None,
    })
}

/// Emit exactly the package's report, including error details and every time.
// Borrow the shared Number alias so BigInt values stay owned by the plan.
#[cfg_attr(
    feature = "checked-i64",
    allow(clippy::needless_borrows_for_generic_args)
)]
fn show(plan: &Plan<'_>, output: &mut Output<impl Write>) -> Result<()> {
    if let Some(error) = &plan.error {
        output.line("ERROR")?;
        output.line(error.kind)?;
        output.line(error.index)?;
        match error.detail {
            Detail::Name(value) => output.line(value)?,
            Detail::Duration(value) => output.line(value)?,
        }
        return Ok(());
    }
    output.line("OK")?;
    output.line("CHANGED")?;
    output.line(plan.changed_count)?;
    output.line("AFFECTED")?;
    output.line(plan.order.len())?;
    output.line("PLAN")?;
    output.line(plan.order.len())?;
    for &task_id in &plan.order {
        output.line(&plan.tasks[task_id].name)?;
        output.line(task_id)?;
        output.line(&plan.tasks[task_id].duration)?;
        output.line(&plan.starts[task_id])?;
        output.line(&plan.finishes[task_id])?;
    }
    output.line("MAKESPAN")?;
    output.line(&plan.makespan)
}

fn run(reader: &mut impl BufRead, output: &mut Output<impl Write>) -> Result<()> {
    let (tasks, changes) = read_problem(reader)?;
    let plan = schedule(&tasks, &changes)?;
    show(&plan, output)?;
    output.flush()
}

fn main() -> ExitCode {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let line_buffered = stdout.is_terminal();
    let mut output = Output::new(stdout.lock(), line_buffered);
    match run(&mut stdin.lock(), &mut output) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            let _ = output.flush();
            let _ = writeln!(io::stderr().lock(), "{}: {}", error.kind, error.message);
            ExitCode::FAILURE
        }
    }
}

// The non-Drop mirror lets successful calls query one TLS byte without
// initializing or checking the owning cell's destructor/borrow state.
// Only replace_pending/take_pending mutate the owner; both synchronize this
// flag before dropping displaced owners. The single-thread, no-callback
// contract makes the brief interval between owner and flag writes unobservable.
static PENDING_PRESENT: Cell<bool> = const { Cell::new(false) };

}

/// Clears presence before transferring the owner, without dropping under a TLS borrow.
fn take_pending() -> Option<Rc<Object>> {
    let pending = PENDING.with(RefCell::take);
    PENDING_PRESENT.set(false);
    pending

}

#[test]
fn replacing_clearing_and_reporting_pending_errors_allow_later_recovery() {
    let first = new_exception(Kind::ValueError, Rc::new(Str::new("first")));
    let second = new_exception(Kind::IndexError, Rc::new(Str::new("second")));
    let weak_first = Rc::downgrade(&first);
    let weak_second = Rc::downgrade(&second);
    // SAFETY: inputs stay rooted through acquisition, then pending state
    // becomes their sole owner. Null explicitly clears that owner.
    unsafe {
        relar_error_set(Rc::as_ptr(&first));
        drop(first);
        assert_eq!(relar_error_pending(), 1);
        relar_error_set(Rc::as_ptr(&second));
        drop(second);
        assert!(weak_first.upgrade().is_none());
        assert_eq!(relar_error_pending(), 1);
        relar_error_set(std::ptr::null());
    }
    assert!(weak_second.upgrade().is_none());
    assert_eq!(relar_error_pending(), 0);
    assert!(relar_error_take().is_null());

    let reported = new_exception(Kind::RuntimeError, Rc::new(Str::new("reported test error")));
    let weak_reported = Rc::downgrade(&reported);
    // SAFETY: pending and active independently acquire this rooted exception.
    unsafe {
        relar_error_set(Rc::as_ptr(&reported));
        assert!(relar_exception_swap_active(Rc::as_ptr(&reported)).is_null());
    }
    drop(reported);
    assert_eq!(relar_error_unhandled(), 1);
    assert!(weak_reported.upgrade().is_none());
    assert_eq!(relar_error_pending(), 0);
    assert!(relar_exception_current().is_null());
    assert_eq!(relar_error_unhandled(), 0);
    for _ in 0..2 {
        relar_exception_reraise();
        assert_eq!(
            message(&take_error(Kind::RuntimeError)).as_str(),
            "No active exception to reraise"
        );
    }

//! Conservative escaping-error summaries over the final, rewritten typed IR.
//!
//! Allocation failure remains fatal under the current runtime contract. Fixed
//! fields cannot raise: the checker fixes their indices, prevents partially
//! initialized objects from escaping, and proves optional payloads present.
//! Container bounds, I/O, conversion, explicit raises and uncertain operations
//! remain fallible. Catching an error does not make its containing function
//! infallible here; every handler, else and finally body is included.

use crate::ir::{Binary, Builtin, Expr, ExprKind, Module, Statement, Type};

pub(crate) struct ExceptionEffects {
    functions: Vec<bool>,
}

impl ExceptionEffects {
    /// True includes uncertainty; false proves no pending error can escape a
    /// call entered without one. Callee arguments are evaluated by the caller
    /// and retain their own checks independently of this summary.
    pub(crate) fn may_raise(&self, function: usize) -> bool {
        self.functions.get(function).copied().unwrap_or(true)
    }
}

/// Removes fallibility only after every operation and callee is proved safe.
/// Starting pessimistically also leaves unexpected recursive cycles fallible;
/// the current frontend rejects them, and its acyclic graph reaches a fixed
/// point after at most one successful transition per function.
pub(crate) fn analyze(module: &Module) -> ExceptionEffects {
    let mut functions = vec![true; module.functions.len()];
    loop {
        let mut changed = false;
        for (id, function) in module.functions.iter().enumerate() {
            if functions[id] && !block(&function.body, &functions) {
                functions[id] = false;
                changed = true;
            }
        }
        if !changed {
            return ExceptionEffects { functions };
        }
    }
}

/// Any potentially failing path is enough; unreachable branches and caught
/// errors deliberately remain conservative rather than requiring control flow.
fn block(body: &[Statement], functions: &[bool]) -> bool {
    body.iter().any(|statement| match statement {
        Statement::Assign(_, value) | Statement::Expr(value) | Statement::Return(value) => {
            expression(value, functions)
        }
        Statement::Move(..) | Statement::Clear(_) | Statement::Break | Statement::Continue => false,
        Statement::Scope { body, .. } => block(body, functions),
        Statement::SetItem(receiver, index, value) => {
            !matches!(receiver.ty, Type::Dict(_))
                || expression(receiver, functions)
                || expression(index, functions)
                || expression(value, functions)
        }
        // The initial indexed read may fail even for a dictionary assignment.
        Statement::AugmentItem(..) => true,
        Statement::SetField(receiver, _, value) => {
            expression(receiver, functions) || expression(value, functions)
        }
        Statement::AugmentField(receiver, _, op, value) => {
            binary(*op) || expression(receiver, functions) || expression(value, functions)
        }
        Statement::If(test, yes, no) => {
            expression(test, functions) || block(yes, functions) || block(no, functions)
        }
        Statement::While(test, body) => expression(test, functions) || block(body, functions),
        Statement::For { args, body, .. } => {
            // The implicit step is exactly one. An explicit step is kept
            // fallible even when a separate range proof could exclude zero.
            !matches!(args.len(), 1 | 2)
                || args.iter().any(|arg| expression(arg, functions))
                || block(body, functions)
        }
        Statement::IterNext { .. } | Statement::Assert(_) | Statement::Raise(_) => true,
        Statement::Try {
            body,
            handlers,
            orelse,
            finalbody,
        } => {
            block(body, functions)
                || handlers
                    .iter()
                    .any(|handler| block(&handler.body, functions))
                || block(orelse, functions)
                || block(finalbody, functions)
        }
    })
}

/// Includes every evaluated child; fixed-layout reads and writes themselves
/// cannot fail, but their receiver, replacement or initializer still can.
fn expression(value: &Expr, functions: &[bool]) -> bool {
    match &value.kind {
        ExprKind::Int(_)
        | ExprKind::Bool(_)
        | ExprKind::Str(_)
        | ExprKind::None
        | ExprKind::Local(_) => false,
        ExprKind::List(values)
        | ExprKind::Tuple(values)
        | ExprKind::Set { values, .. }
        | ExprKind::Compare(values, _)
        | ExprKind::Boolean(_, values) => values.iter().any(|value| expression(value, functions)),
        ExprKind::Dict { entries, .. } => entries
            .iter()
            .any(|(key, value)| expression(key, functions) || expression(value, functions)),
        ExprKind::Present(value)
        | ExprKind::Absent(value)
        | ExprKind::Unwrap(value)
        | ExprKind::Not(value)
        | ExprKind::Negate(value)
        | ExprKind::Field(value, _) => expression(value, functions),
        ExprKind::Binary(op, left, right) => {
            binary(*op) || expression(left, functions) || expression(right, functions)
        }
        ExprKind::Call(id, args) => {
            functions.get(*id).copied().unwrap_or(true)
                || args.iter().any(|arg| expression(arg, functions))
        }
        ExprKind::Construct {
            initializer, args, ..
        } => {
            functions.get(*initializer).copied().unwrap_or(true)
                || args.iter().any(|arg| expression(arg, functions))
        }
        ExprKind::Exception { message, .. } => message
            .as_ref()
            .is_some_and(|message| expression(message, functions)),
        ExprKind::Builtin(builtin, args) => {
            builtin_raises(builtin, args) || args.iter().any(|arg| expression(arg, functions))
        }
    }
}

fn binary(op: Binary) -> bool {
    match op {
        Binary::FloorDivide | Binary::Modulo | Binary::Repeat => true,
        Binary::Add | Binary::Subtract | Binary::Multiply | Binary::Concat => false,
    }
}

/// Classifies only the builtin's own work. Argument evaluation is accounted
/// separately, including eager defaults on otherwise infallible dictionary lookups.
fn builtin_raises(builtin: &Builtin, args: &[Expr]) -> bool {
    match builtin {
        Builtin::Print
        | Builtin::Input
        | Builtin::ListGet
        | Builtin::Pop
        | Builtin::DictGet
        | Builtin::DictDelete => true,
        Builtin::Int => args
            .first()
            .is_none_or(|arg| !matches!(arg.ty, Type::Int | Type::Bool)),
        Builtin::Len
        | Builtin::Append
        | Builtin::IsNone
        | Builtin::Split
        | Builtin::DictGetDefault
        | Builtin::DictTryGet(_)
        | Builtin::DictContains
        | Builtin::DictIter(_)
        | Builtin::SetContains
        | Builtin::SetAdd
        | Builtin::SetDiscard
        | Builtin::SetIter
        | Builtin::ExceptionMessage => false,
    }
}

